INSERT INTO `sessions` VALUES ('066c1860-2bcf-4e1a-9e19-24283d524f8c','风能的价格标准','2026-04-10 10:29:48','2026-04-11 10:08:27',4),('1824b2d4-95c4-4939-9417-ba8599a87b59','风能的价格标准','2026-04-19 08:43:51','2026-04-19 08:48:54',6),('1f5ab6cd-1745-45a8-85fe-80b391f2cc7b','新能源和传统能源相比有什么不足？','2026-04-08 09:43:42','2026-04-08 09:45:22',2),('21794d1f-321c-465b-9cb5-d7c917327e40','风能的价格标准，给我具体的数字','2026-04-20 15:50:52','2026-04-20 15:52:14',2),('2e325ed4-804c-46be-9361-c42d0430bd51','水能的价格标准','2026-04-21 12:13:00','2026-04-21 12:15:45',2),('2f6ef6c5-c8d1-43ef-92ca-f85f29589d99','2025年新颁布的能源政策','2026-04-07 14:43:27','2026-04-07 14:48:26',2),('33d5bd0b-b37b-472c-b534-55b1e5cf298f','风能是新能源吗？','2026-04-12 09:46:36','2026-04-12 09:47:51',2),('5bb440d2-32a4-4fe1-a4a8-ca54116c981e','我国现在的能源政策','2026-04-21 14:03:04','2026-04-21 14:04:51',2),('72ba7bad-1552-4bc4-a7e3-48de78681b57','新能源的技术标准','2026-04-02 13:58:33','2026-04-02 14:06:48',6),('73605f8d-754a-4922-b794-f03d95d7f414','江西省的能源政策','2026-04-01 21:47:37','2026-04-01 21:50:04',2),('79a6ce46-4f1e-4dbc-9ed3-786107154f29','新能源主要包括些什么？','2026-04-12 09:34:35','2026-04-12 09:38:20',4),('7ef30429-e8d9-44cd-9804-15c6ec93dc01','新能源的应用场景','2026-04-09 12:21:24','2026-04-09 12:25:27',2),('9a9ca120-ea64-4ed7-8ab7-62099d5d0901','风能的技术标准','2026-04-08 09:56:51','2026-04-08 09:58:39',2),('aa0e717e-2e36-4457-967d-e32f958f098a','氢能产业发展中长期规划','2026-04-13 13:22:41','2026-04-13 13:25:00',2),('c23f5091-9c9c-4a07-9273-3de68320cc2c','什么是新能源','2026-04-11 15:02:19','2026-04-11 15:04:00',2),('d1e22725-efd9-4eca-8821-36801f348e9c','新能源相比于传统能源有什么优势','2026-04-08 09:37:29','2026-04-08 09:38:57',2),('e1415eba-17d1-4702-a6ed-b24aaa732a5a','水电的价格标准','2026-04-20 08:44:44','2026-04-20 08:47:15',4);
