UNLOCK TABLES;

--
-- Temporary view structure for view `v_stats`
--

DROP TABLE IF EXISTS `v_stats`;
/*!50001 DROP VIEW IF EXISTS `v_stats`*/;
SET @saved_cs_client     = @@character_set_client;
/*!50503 SET character_set_client = utf8mb4 */;
/*!50001 CREATE VIEW `v_stats` AS SELECT 
 1 AS `total_sessions`,
 1 AS `total_questions`,
 1 AS `avg_response_time`,
 1 AS `total_likes`,
 1 AS `total_dislikes`*/;
SET character_set_client = @saved_cs_client;

--
-- Final view structure for view `v_stats`
--

/*!50001 DROP VIEW IF EXISTS `v_stats`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = gbk */;
/*!50001 SET character_set_results     = gbk */;
/*!50001 SET collation_connection      = gbk_chinese_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_stats` AS select count(distinct `s`.`id`) AS `total_sessions`,count(distinct (case when (`m`.`role` = 'user') then `m`.`id` end)) AS `total_questions`,round(avg((case when (`m`.`role` = 'assistant') then `m`.`elapsed_seconds` end)),2) AS `avg_response_time`,sum((case when (`r`.`rating` = 1) then 1 else 0 end)) AS `total_likes`,sum((case when (`r`.`rating` = -(1)) then 1 else 0 end)) AS `total_dislikes` from ((`sessions` `s` left join `messages` `m` on((`m`.`session_id` = `s`.`id`))) left join `ratings` `r` on((`r`.`message_id` = `m`.`id`))) */;
